#[test]
fn root_help_succeeds_and_shows_only_root_surface() {
    let help = help_text(&["tool", "--help"]);
    for needle in [
        "--config",
        "<path>",
        "builtin.toml",
        "--define",
        "<key=value>",
        "serve",
        "check",
        "captured as a root plugin",
