#![cfg(feature = "help")]
#![cfg(feature = "usage")]

use clap::Arg;
use clap::ArgAction;
use clap::Command;
use clap::value_parser;
use clap::error::ErrorKind;

fn parse_define(raw: &str) -> Result<(String, String), String> {
    let Some((key, value)) = raw.split_once('=') else {
        return Err(format!("invalid define `{raw}`: expected key=value"));
    };
    if value.contains('=') {
        return Err(format!("invalid define `{raw}`: expected exactly one `=`"));
    }
    if key.is_empty() {
        return Err(format!("invalid define `{raw}`: key must not be empty"));
    }
    if value.is_empty() {
        return Err(format!("invalid define `{raw}`: value must not be empty"));
    }
    if key.chars().any(char::is_whitespace) || value.chars().any(char::is_whitespace) {
        return Err(format!("invalid define `{raw}`: no whitespace"));
    }
    Ok((key.to_owned(), value.to_owned()))
}

fn parse_port(raw: &str) -> Result<u16, String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("invalid port `{raw}`: decimal 1..=65535"));
    }
    match raw.parse::<u32>() {
        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
        _ => Err(format!("invalid port `{raw}`: decimal 1..=65535")),
    }
}

fn tool() -> Command {
    Command::new("tool")
        .after_help("External plugins: any other <COMMAND> is captured as a root plugin.")
        .arg(
            Arg::new("config")
                .long("config")
                .global(true)
                .default_value("builtin.toml")
                .value_name("path"),
        )
        .arg(
            Arg::new("define")
                .long("define")
                .value_name("key=value")
                .action(ArgAction::Append)
                .value_parser(value_parser!(String).map_ref(|s| parse_define(s).unwrap())),
        )
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            Command::new("serve")
                .after_help("External plugins: any other <COMMAND> is captured as a serve plugin.")
                .subcommand_required(true)
                .arg_required_else_help(true)
                .allow_external_subcommands(true)
                .external_subcommand_value_parser(value_parser!(String))
                .subcommand(
                    Command::new("worker")
                        .arg(
                            Arg::new("port")
                                .long("port")
                                .required(true)
                                .value_name("port")
                                .value_parser(parse_port),
                        )
                        .arg(
                            Arg::new("http")
                                .long("http")
                                .action(ArgAction::SetTrue)
                                .conflicts_with("https"),
                        )
                        .arg(
                            Arg::new("https")
                                .long("https")
                                .action(ArgAction::SetTrue)
                                .conflicts_with("http"),
                        )
                        .arg(
                            Arg::new("trailing")
                                .action(ArgAction::Append)
                                .last(true)
                                .num_args(1..),
                        ),
                ),
        )
        .subcommand(
            Command::new("check")
                .arg(Arg::new("path").action(ArgAction::Set))
                .arg(Arg::new("strict").long("strict").action(ArgAction::SetTrue)),
        )
        .allow_external_subcommands(true)
        .external_subcommand_value_parser(value_parser!(String))
}

#[test]
fn scratch() {
    let m = tool()
        .try_get_matches_from(["tool", "--define", "a=1", "serve", "worker", "--port", "8080", "--http", "--", "z", "--define"])
        .unwrap();
    let (_, sm) = m.subcommand().unwrap();
    let (_, wm) = sm.subcommand().unwrap();
    println!("config root={:?}", m.get_one::<String>("config"));
    println!("config worker={:?}", wm.get_one::<String>("config"));
    println!("port={:?}", wm.get_one::<u16>("port"));
    println!("http={:?}", wm.get_one::<bool>("http"));
    println!("trailing={:?}", wm.get_many::<String>("trailing").map(|i| i.collect::<Vec<_>>()));
    println!("define root={:?}", m.get_many::<(String, String)>("define").map(|i| i.collect::<Vec<_>>()));

    let m = tool().try_get_matches_from(["tool", "plug", "--define", "x=y"]).unwrap();
    let (name, em) = m.subcommand().unwrap();
    println!("ext name={name} args={:?}", em.get_many::<String>("").unwrap().collect::<Vec<_>>());
}

#[test]
fn scratch_help() {
    for argv in [
        vec!["tool", "--help"],
        vec!["tool", "serve", "--help"],
        vec!["tool", "serve", "worker", "--help"],
        vec!["tool", "check", "--help"],
    ] {
        let err = tool().try_get_matches_from(argv.clone()).unwrap_err();
        assert_eq!(err.kind(), ErrorKind::DisplayHelp);
        println!("==== {argv:?} ====\n{err}");
    }
}

#[test]
fn scratch_errors() {
    for argv in [
        vec!["tool", "--define", "=v", "check"],
        vec!["tool", "--define"],
        vec!["tool", "serve", "worker"],
        vec!["tool", "serve", "worker", "--port", "80", "--port", "90"],
        vec!["tool", "serve", "--define", "a=1", "plug"],
        vec!["tool"],
        vec!["tool", "serve"],
        vec!["tool", "check", "a", "b"],
    ] {
        let r = tool().try_get_matches_from(argv.clone());
        match r {
            Ok(m) => println!("{argv:?} => OK sub={:?}", m.subcommand().map(|(n, _)| n)),
            Err(e) => println!("{argv:?} => {:?}\n{e}", e.kind()),
        }
    }
}

