fn probe() {
    let m = tool()
        .try_get_matches_from(["tool", "serve", "worker", "--port", "80", "--", "z", "--", "", "--port"])
        .unwrap();
    let (_, sm) = m.subcommand().unwrap();
    let (_, wm) = sm.subcommand().unwrap();
    println!("trailing={:?}", wm.get_many::<String>("trailing").unwrap().collect::<Vec<_>>());

    // serve external captures flag-like tokens verbatim
    let m = tool().try_get_matches_from(["tool", "serve", "plug", "--http", "x", "--", ""]).unwrap();
