    println!("serve-level config={:?}", sm.get_one::<String>("config"));

    // --help after external name is plugin data
    let m = tool().try_get_matches_from(["tool", "plug", "--help"]).unwrap();
    let (n, em) = m.subcommand().unwrap();
    println!("root ext name={n} args={:?}", em.get_many::<String>("").unwrap().collect::<Vec<_>>());

    // root level separator forcing plugin
    let m = tool().try_get_matches_from(["tool", "--", "", "rest"]).unwrap();
    let (n, em) = m.subcommand().unwrap();
    println!("root -- name={n:?} args={:?}", em.get_many::<String>("").unwrap().collect::<Vec<_>>());

    // defines order across positions (root only)
    let m = tool().try_get_matches_from(["tool", "--define", "a=1", "check", "--define", "b=2"]).unwrap_err();
    println!("check --define => {:?}", m.kind());
}

