    println!("worker-level config: root={:?} serve={:?} worker={:?}",
        m.get_one::<String>("config"), sm.get_one::<String>("config"), wm.get_one::<String>("config"));

    // config at serve level, read at worker
    let m = tool().try_get_matches_from(["tool", "serve", "--config", "s.toml", "worker", "--port", "80"]).unwrap();
    let (_, sm) = m.subcommand().unwrap();
    let (_, wm) = sm.subcommand().unwrap();
